mapper.select:
SELECT task_id AS taskId, stage, step_order AS stepOrder, status, error_code AS errorCode, error_message AS errorMessage, started_at AS startedAt, finished_at AS finishedAt FROM task_step WHERE task_id IN
#{taskId}
ORDER BY task_id ASC, step_order ASC

mapper.update:
UPDATE task_step
SET status = 'RUNNING',
    started_at = #{startedAt}
WHERE task_id = #{taskId}
  AND stage = #{stage}
  AND status = 'PENDING'

UPDATE task_step
SET status = 'SUCCEEDED',
    finished_at = #{finishedAt}
WHERE task_id = #{taskId}
  AND stage = #{stage}
  AND status = 'RUNNING'

UPDATE task_step
SET status = 'FAILED',
    error_code = #{errorCode},
    error_message = #{errorMessage},
    finished_at = #{finishedAt}
WHERE task_id = #{taskId}
  AND stage = #{stage}

UPDATE task_step
SET status = 'SKIPPED',
    finished_at = #{finishedAt}
WHERE task_id = #{taskId}
  AND status = 'PENDING'
